import java.util.concurrent.*;
class OwnedWork {
    static <T> T run(Callable<T> task) throws InterruptedException, ExecutionException, TimeoutException {
        var executor = Executors.newSingleThreadExecutor();
        Future<T> future = executor.submit(task);
        try { return future.get(2,TimeUnit.SECONDS); }
        finally {
            future.cancel(true);
            executor.shutdownNow();
            if (!executor.awaitTermination(2,TimeUnit.SECONDS)) throw new IllegalStateException("worker did not stop");
        }
    }
}

