        assertThrows(java.io.IOException.class, () -> Files.readString(report));
    }
}

import java.util.concurrent.*;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;
class AsyncParsingTest {
    static Stream<Arguments> numbers() { return Stream.of(Arguments.of("0",0),Arguments.of("42",42),Arguments.of("-1",-1)); }
    @ParameterizedTest @MethodSource("numbers")
    void parses(String text, int expected) throws Exception {
        var result = CompletableFuture.completedFuture(text).thenApply(Integer::parseInt);
        assertEquals(expected,result.get(2,TimeUnit.SECONDS));
    }
    @Test void observesFailure() {
        var result = CompletableFuture.completedFuture("bad").thenApply(Integer::parseInt);
        var error = assertThrows(ExecutionException.class, () -> result.get(2,TimeUnit.SECONDS));
        assertInstanceOf(NumberFormatException.class,error.getCause());
    }
}

import java.util.List;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.web.bind.annotation.*;
@RestController
class BatchController {
    record Item(@NotBlank String name, @Positive @Max(1_000_000) int quantity) {}
    record Batch(@NotNull @Size(min=1,max=3) List<@NotNull @Valid Item> items) {}
    @PostMapping("/batches")
    int total(@Valid @RequestBody Batch batch) {
        return batch.items().stream().mapToInt(Item::quantity).sum();
    }
}

